-- Technical P02 fixture only. No production startup migration is performed.
CREATE SCHEMA IF NOT EXISTS muskdeer_p02;
CREATE TABLE IF NOT EXISTS muskdeer_p02.storage_probes (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    create_at BIGINT NOT NULL,
    update_at BIGINT NOT NULL,
    delete_at BIGINT NULL,
    venue VARCHAR(32) NOT NULL,
    instrument VARCHAR(64) NOT NULL,
    price NUMERIC(38,18) NOT NULL,
    enabled BOOLEAN NOT NULL,
    revision BIGINT NOT NULL,
    CONSTRAINT uk_storage_probe_market UNIQUE (venue, instrument)
);
